package com.bananalab.lite;
import java.util.*;import java.util.regex.*;import org.json.*;
/** General Java edits; free-form behavior synthesis is not implemented. */
final class GeneralEditPlan{
 final JSONArray edits;GeneralEditPlan(JSONArray e)throws Exception{edits=new JSONArray(e.toString());if(edits.length()<1||edits.length()>16)throw new IllegalArgumentException("Hasta16 operaciones por lote");}
 static String ident(String s){if(!s.matches("[A-Za-z_$][A-Za-z0-9_$]{0,70}")||s.matches("class|interface|enum|return|if|else|for|while|int|float|double|boolean|long|byte|char|short|void|public|private|protected|static|final|this|super|new|null|true|false|try|catch|throw|throws|finally|do|switch|case|default|break|continue|instanceof|import|package|extends|implements|abstract|native|volatile|transient|synchronized|strictfp|assert|const|goto"))throw new IllegalArgumentException("Identificador inválido");return s;}
 static GeneralEditPlan parse(String raw)throws Exception{String s=NaturalCoding.polite(raw).trim().replaceFirst("(?iu)^cambies\\b","cambia").replaceFirst("(?iu)^reescribas\\b","reescribe").replaceFirst("(?iu)^reemplaces\\b","reemplaza").replaceFirst("(?iu)^crees\\b","crea").replaceFirst("(?iu)^renombres\\b","renombra");JSONObject e=new JSONObject();Matcher m=Pattern.compile("(?isu)^(?:cambia|cambiame|reemplaza|sustituye) (?:el texto |la cadena )?("+JavaTextPlan.LIT+") por ("+JavaTextPlan.LIT+") en (toda la app|todo el codigo|[A-Z][A-Za-z0-9_]*\\.java)[.! ]*$").matcher(s);if(m.matches())e.put("op","literal").put("file",m.group(3).endsWith(".java")?m.group(3):"*").put("from",JavaTextPlan.decode(m.group(1))).put("to",JavaTextPlan.decode(m.group(2)));else{m=Pattern.compile("(?isu)^(?:renombra|renombrame|cambia el nombre de) (?:el identificador |el simbolo )?([A-Za-z_$][A-Za-z0-9_$]*) (?:por|a) ([A-Za-z_$][A-Za-z0-9_$]*) en (?:toda la app|todo el codigo)[.! ]*$").matcher(s);if(m.matches())e.put("op","rename").put("file","*").put("from",ident(m.group(1))).put("to",ident(m.group(2)));else{m=Pattern.compile("(?isu)^(?:cambia|cambiame|reescribe|reemplaza) (?:el )?metodo ([A-Za-z_$][A-Za-z0-9_$]*) (?:de|en) ([A-Z][A-Za-z0-9_]*\\.java) (?:por|con)(?: este codigo)?\\s*:\\s*```(?:java)?\\s*\\n(.*?)\\n```\\s*$").matcher(s);if(m.matches())e.put("op","method").put("file",m.group(2)).put("method",ident(m.group(1))).put("source",m.group(3));else{m=Pattern.compile("(?isu)^(?:reemplaza|reescribe|crea|agrega) (?:el archivo )?([A-Z][A-Za-z0-9_]*\\.java) (?:por|con)(?: este codigo)?\\s*:\\s*```(?:java)?\\s*\\n(.*?)\\n```\\s*$").matcher(s);if(!m.matches())return null;e.put("op","file").put("file",m.group(1)).put("source",m.group(2));}}}return new GeneralEditPlan(new JSONArray().put(e));}
 Map<String,String> apply(Map<String,String> base)throws Exception{Map<String,String> all=new TreeMap<>(base);for(int i=0;i<edits.length();i++){JSONObject e=edits.getJSONObject(i);String op=e.getString("op"),file=e.getString("file");if(!file.equals("*"))JavaSourceEdit.filename(file);if(op.equals("file")){RuntimeProgram.keys(e,"op","file","source");if(file.equals("*"))throw new IllegalArgumentException("Falta archivo");all.put(file,e.getString("source"));}else if(op.equals("method")){RuntimeProgram.keys(e,"op","file","method","source");if(!all.containsKey(file))throw new IllegalArgumentException("No encontré "+file);if(SourceLex.unicode(all.get(file)))throw new IllegalArgumentException("Método con escapes Unicode: proporcioná el archivo completo");all.put(file,JavaSourceEdit.replace(all.get(file),ident(e.getString("method")),e.getString("source")));}else{RuntimeProgram.keys(e,"op","file","from","to");String from=e.getString("from"),to=e.getString("to");if(op.equals("rename")){ident(from);ident(to);}else if(!op.equals("literal"))throw new IllegalArgumentException("Operación desconocida");boolean found=false;for(String name:new ArrayList<String>(all.keySet()))if(file.equals("*")||file.equals(name)){found=true;all.put(name,op.equals("rename")?SourceLex.rename(all.get(name),from,to):SourceLex.literal(all.get(name),from,to));}if(!found)throw new IllegalArgumentException("Archivo inexistente");}}
 Map<String,String> changed=new TreeMap<>();for(Map.Entry<String,String> e:all.entrySet())if(!e.getValue().equals(base.get(e.getKey()))){String text=e.getValue();if(text.length()>150000||!SourceLex.masked(text).matches("(?s)\\s*package\\s+com\\.bananalab\\.lite\\s*;.*"))throw new IllegalArgumentException("Fuente fuera del paquete o tamaño: "+e.getKey());changed.put(e.getKey(),text);}if(changed.isEmpty())throw new IllegalArgumentException("No encontré cambios aplicables");if(new JSONObject(changed).toString().length()>1000000)throw new IllegalArgumentException("Lote superior a1MB");return changed;}
}
